import type { Scheme } from './types';

// Initial directory of real, named government programmes. Details are intentionally
// directed to official pages so users can verify current eligibility and deadlines.
const records: Array<Omit<Scheme,'verificationStatus'|'lastVerified'>> = [
{id:'pm-kisan',name:{en:'Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)',te:'ప్రధాన మంత్రి కిసాన్ సమ్మాన్ నిధి (PM-KISAN)'},scope:'central',states:[],summary:{en:'Income-support programme for eligible landholding farmer families. Check the official portal for current conditions.',te:'అర్హత కలిగిన భూమి కలిగిన రైతు కుటుంబాల కోసం ఆదాయ సహాయ పథకం. ప్రస్తుత నిబంధనలను అధికారిక పోర్టల్‌లో చూడండి.'},eligibility:{en:['For eligible landholding farmer families; the cultivable landholding must be recorded in the land records.','Institutional landholders are excluded.','Certain higher-income or public-office categories are excluded, including specified serving/retired government employees, income-tax payers, and specified professionals; check the official exclusion list.','The beneficiary family is defined under the scheme rules; verify that all family and land-record details match official records.'],te:['అర్హత కలిగిన భూమి కలిగిన రైతు కుటుంబాలకు వర్తిస్తుంది; సాగుభూమి హక్కులు భూ రికార్డుల్లో నమోదు అయి ఉండాలి.','సంస్థల పేరుతో ఉన్న భూమి హక్కుదారులు అర్హులు కారు.','కొన్ని అధిక ఆదాయ లేదా ప్రభుత్వ పదవుల వర్గాలు మినహాయించబడతాయి. ఇందులో నిర్దిష్ట ప్రభుత్వ ఉద్యోగులు, ఆదాయపు పన్ను చెల్లింపుదారులు, కొన్ని వృత్తిపరమైన వర్గాలు ఉండవచ్చు; అధికారిక మినహాయింపుల జాబితాను చూడండి.','పథకం నిబంధనల ప్రకారం రైతు కుటుంబాన్ని నిర్వచిస్తారు; కుటుంబం, భూ రికార్డుల వివరాలు అధికారిక రికార్డులతో సరిపోతున్నాయో నిర్ధారించండి.']},documents:{en:['Aadhaar details for identity verification, as required by the scheme.','Bank account details and account information for payment.','Landholding/land-record details as required by the state and scheme workflow.','Complete the required e-KYC and correct any name, Aadhaar, bank, or land-record mismatch through the official process.'],te:['పథకం ప్రకారం గుర్తింపు ధృవీకరణకు ఆధార్ వివరాలు.','చెల్లింపుల కోసం బ్యాంకు ఖాతా వివరాలు.','రాష్ట్రం, పథక విధానం కోరిన భూ హక్కులు/భూ రికార్డుల వివరాలు.','అవసరమైన e-KYC పూర్తి చేసి, పేరు, ఆధార్, బ్యాంకు లేదా భూ రికార్డుల్లో తేడాలుంటే అధికారిక విధానంలో సరిచేయండి.']},steps:{en:['Open the official PM-KISAN portal.','Check beneficiary status, eligibility, and current application instructions.'],te:['అధికారిక PM-KISAN పోర్టల్‌ను తెరవండి.','లబ్ధిదారుడి స్థితి, అర్హత, ప్రస్తుత దరఖాస్తు సూచనలను చూడండి.']},officialUrl:'https://pmkisan.gov.in/',category:'agriculture'},
{id:'pmfby',name:{en:'Pradhan Mantri Fasal Bima Yojana (PMFBY)',te:'ప్రధాన మంత్రి ఫసల్ బీమా యోజన (PMFBY)'},scope:'central',states:[],summary:{en:'Crop insurance programme. Availability, notified crops, and enrolment windows vary by season and area.',te:'పంటల బీమా పథకం. అందుబాటు, నోటిఫై చేసిన పంటలు, నమోదు గడువులు సీజన్ మరియు ప్రాంతాన్ని బట్టి మారుతాయి.'},eligibility:{en:['The farmer must have an insurable interest in the notified crop and land for the relevant season.','The crop and village/area must be notified for coverage in that season.','Both landowner and eligible tenant/sharecropper cultivators may qualify where the state notification and required proof allow it.','Enrollment deadlines, notified crops, risks covered and premium share vary by season and state; verify the current notification.'],te:['సంబంధిత సీజన్‌లో నోటిఫై చేసిన పంట, భూమిపై రైతుకు బీమా ప్రయోజన హక్కు ఉండాలి.','ఆ సీజన్‌కు పంట, గ్రామం/ప్రాంతం నోటిఫై అయి ఉండాలి.','రాష్ట్ర నోటిఫికేషన్, అవసరమైన ఆధారాలు అనుమతించే చోట భూ యజమానులు, అర్హ కౌలు/భాగస్వామ్య రైతులు కూడా అర్హులు కావచ్చు.','నమోదు గడువు, పంటలు, కవర్ చేసే ప్రమాదాలు, ప్రీమియం వాటా సీజన్, రాష్ట్రాన్ని బట్టి మారుతాయి; ప్రస్తుత నోటిఫికేషన్‌ను నిర్ధారించండి.']},documents:{en:['Aadhaar or accepted government photo ID.','Land record/passbook or accepted lease/tenancy proof.','Crop-sowing certificate/details if required for the notified crop and season.','Bank passbook/account details for claim settlement.','Current season/state notification and premium/loan details where applicable.'],te:['ఆధార్ లేదా ఆమోదిత ప్రభుత్వ ఫోటో గుర్తింపు పత్రం.','భూ హక్కుల రికార్డు/పాస్‌బుక్ లేదా ఆమోదిత కౌలు ఆధారం.','అవసరమైతే పంట విత్తన ధృవీకరణ/పంట వివరాలు.','క్లెయిమ్ కోసం బ్యాంకు పాస్‌బుక్/ఖాతా వివరాలు.','ప్రస్తుత సీజన్/రాష్ట్ర నోటిఫికేషన్, వర్తించే ప్రీమియం/రుణ వివరాలు.']},steps:{en:['Review the current crop and area notification.','Follow the official enrolment instructions within the applicable window.'],te:['ప్రస్తుత పంట, ప్రాంత నోటిఫికేషన్‌ను పరిశీలించండి.','వర్తించే గడువులో అధికారిక నమోదు సూచనలను అనుసరించండి.']},officialUrl:'https://pmfby.gov.in/',category:'agriculture'},
{id:'pmjdy',name:{en:'Pradhan Mantri Jan-Dhan Yojana (PMJDY)',te:'ప్రధాన మంత్రి జన్-ధన్ యోజన (PMJDY)'},scope:'central',states:[],summary:{en:'National financial-inclusion programme focused on access to basic banking services.',te:'ప్రాథమిక బ్యాంకింగ్ సేవలకు ప్రాప్యతను ప్రోత్సహించే జాతీయ ఆర్థిక సమగ్రత పథకం.'},eligibility:{en:['A person who does not already have a bank account can open a basic savings bank deposit account at a participating bank branch or Bank Mitra outlet.','No minimum balance is required for the basic PMJDY account.','Overdraft and insurance-related benefits have additional eligibility and usage conditions; opening an account alone does not guarantee every benefit.'],te:['ఇప్పటికే బ్యాంకు ఖాతా లేని వ్యక్తి పాల్గొనే బ్యాంకు శాఖ లేదా బ్యాంక్ మిత్ర కేంద్రంలో ప్రాథమిక పొదుపు ఖాతా తెరవవచ్చు.','PMJDY ప్రాథమిక ఖాతాకు కనీస నిల్వ అవసరం లేదు.','ఓవర్‌డ్రాఫ్ట్, బీమా ప్రయోజనాలకు అదనపు అర్హతలు, వినియోగ నిబంధనలు ఉంటాయి; ఖాతా తెరిచినంత మాత్రాన అన్ని ప్రయోజనాలు హామీ కావు.']},documents:{en:['Aadhaar if available, or another bank-accepted KYC identity/address document.','Voter ID/PAN/passport/utility bill or other officially accepted proof as applicable.','Passport-size photograph if requested.','Completed basic savings account opening form.'],te:['ఉంటే ఆధార్; లేకపోతే బ్యాంకు అంగీకరించే KYC గుర్తింపు/చిరునామా పత్రం.','వర్తించే విధంగా ఓటర్ ఐడీ/PAN/పాస్‌పోర్ట్/యుటిలిటీ బిల్లు వంటి ఆమోదిత ఆధారం.','అడిగితే పాస్‌పోర్ట్ సైజు ఫోటో.','పూర్తి చేసిన ప్రాథమిక పొదుపు ఖాతా దరఖాస్తు.']},steps:{en:['Read the official scheme information.','Contact a participating bank for account-opening requirements.'],te:['అధికారిక పథక సమాచారాన్ని చదవండి.','ఖాతా ప్రారంభ అవసరాల కోసం పాల్గొనే బ్యాంకును సంప్రదించండి.']},officialUrl:'https://www.pmjdy.gov.in/',category:'banking'},
{id:'mudra',name:{en:'Pradhan Mantri MUDRA Yojana (PMMY)',te:'ప్రధాన మంత్రి ముద్ర యోజన (PMMY)'},scope:'central',states:[],summary:{en:'Loans through eligible lending institutions for qualifying non-corporate, non-farm micro and small enterprises.',te:'అర్హత కలిగిన వ్యవసాయేతర సూక్ష్మ, చిన్న వ్యాపారాల కోసం రుణ సంస్థల ద్వారా రుణాలు.'},eligibility:{en:['Individuals with a viable business plan for an eligible non-corporate, non-farm micro or small income-generating enterprise may apply through a member lending institution.','Eligible activities include manufacturing, trading, services and certain activities allied to agriculture.','Loan categories are Shishu (up to ₹50,000), Kishor (above ₹50,000 to ₹5 lakh), Tarun (above ₹5 lakh to ₹10 lakh), and Tarun Plus (above ₹10 lakh to ₹20 lakh for borrowers who successfully repaid a previous Tarun loan).','The lender assesses creditworthiness and documents; approval, amount and terms are not guaranteed.'],te:['అర్హ వ్యవసాయేతర సూక్ష్మ/చిన్న ఆదాయార్జన వ్యాపారానికి సాధ్యమైన వ్యాపార ప్రణాళిక ఉన్న వ్యక్తులు సభ్య రుణ సంస్థ ద్వారా దరఖాస్తు చేయవచ్చు.','తయారీ, వ్యాపారం, సేవలు మరియు వ్యవసాయ అనుబంధంలోని కొన్ని కార్యకలాపాలు అర్హంగా ఉండవచ్చు.','రుణ విభాగాలు: శిశు (₹50,000 వరకు), కిశోర్ (₹50,000 పైగా–₹5 లక్షల వరకు), తరుణ్ (₹5 లక్షల పైగా–₹10 లక్షల వరకు), తరుణ్ ప్లస్ (గత తరుణ్ రుణాన్ని విజయవంతంగా తిరిగి చెల్లించిన వారికి ₹10 లక్షల పైగా–₹20 లక్షల వరకు).','రుణదాత క్రెడిట్ సామర్థ్యం, పత్రాలను పరిశీలిస్తారు; ఆమోదం, మొత్తం, నిబంధనలు హామీ కావు.']},documents:{en:['Identity/address proof and PAN as requested by lender.','Business registration/licence/Udyam details if applicable.','Business plan/project report, cost estimate and supplier quotations.','Bank statements and existing-loan details if requested.','Lender-specific application and category documents, where applicable.'],te:['రుణదాత కోరే గుర్తింపు/చిరునామా పత్రం, PAN.','వర్తిస్తే వ్యాపార రిజిస్ట్రేషన్/లైసెన్స్/Udyam వివరాలు.','వ్యాపార ప్రణాళిక/ప్రాజెక్ట్ నివేదిక, ఖర్చుల అంచనా, కొటేషన్లు.','అడిగితే బ్యాంకు స్టేట్‌మెంట్లు, ప్రస్తుత రుణ వివరాలు.','వర్తించే ఇతర రుణదాత పత్రాలు.']},steps:{en:['Review official MUDRA information.','Contact an eligible lending institution and check its application process.'],te:['అధికారిక ముద్ర సమాచారాన్ని చూడండి.','అర్హ రుణ సంస్థను సంప్రదించి దరఖాస్తు విధానాన్ని తెలుసుకోండి.']},officialUrl:'https://www.mudra.org.in/',category:'business'},
{id:'pmvishwakarma',name:{en:'PM Vishwakarma',te:'పీఎం విశ్వకర్మ'},scope:'central',states:[],summary:{en:'Support programme for eligible traditional artisans and craftspeople, subject to scheme conditions.',te:'పథకం నిబంధనలకు లోబడి అర్హత కలిగిన సంప్రదాయ కళాకారులు, చేతివృత్తిదారుల కోసం సహాయ కార్యక్రమం.'},eligibility:{en:['Applicant must be at least 18 on registration day and self-employed in the unorganised sector, working with hands/tools in one of the scheme’s 18 listed traditional trades.','Applicant must be actively engaged in that trade at registration.','Generally, only one family member (husband, wife and unmarried children) can register.','People in government service and their family members are excluded. Similar government self-employment/business loans in the preceding five years can affect eligibility; check the official rules for exceptions.'],te:['నమోదు రోజున కనీసం 18 ఏళ్లు ఉండాలి; అసంఘటిత రంగంలో స్వయం ఉపాధితో, పథకంలోని 18 సంప్రదాయ వృత్తుల్లో ఒకదానిలో చేతులు/పరికరాలతో పని చేయాలి.','నమోదు సమయంలో ఆ వృత్తిలో చురుకుగా పనిచేస్తుండాలి.','సాధారణంగా ఒక కుటుంబం (భర్త, భార్య, అవివాహిత పిల్లలు) నుంచి ఒకరే నమోదు చేసుకోవచ్చు.','ప్రభుత్వ ఉద్యోగులు, వారి కుటుంబ సభ్యులు అర్హులు కారు. గత ఐదేళ్లలో తీసుకున్న ఇలాంటి ప్రభుత్వ స్వయం ఉపాధి/వ్యాపార రుణాలు అర్హతపై ప్రభావం చూపవచ్చు; మినహాయింపుల కోసం అధికారిక నియమాలు చూడండి.']},documents:{en:['Aadhaar and mobile number.','Bank account/passbook details.','Ration card; if unavailable, Aadhaar details of all family members as instructed.','Trade/occupation details for CSC verification.'],te:['ఆధార్, మొబైల్ నంబర్.','బ్యాంకు ఖాతా/పాస్‌బుక్ వివరాలు.','రేషన్ కార్డు; లేకపోతే సూచించిన విధంగా కుటుంబ సభ్యులందరి ఆధార్ వివరాలు.','CSC ధృవీకరణ కోసం వృత్తి వివరాలు.']},steps:{en:['Check the listed trades and eligibility.','Follow the official registration and verification process.'],te:['జాబితాలోని వృత్తులు, అర్హతను చూడండి.','అధికారిక నమోదు, ధృవీకరణ విధానాన్ని అనుసరించండి.']},officialUrl:'https://pmvishwakarma.gov.in/',category:'business'},
{id:'national-scholarship-portal',name:{en:'National Scholarship Portal (NSP)',te:'జాతీయ స్కాలర్‌షిప్ పోర్టల్ (NSP)'},scope:'central',states:[],summary:{en:'Official gateway for multiple central and other scholarships; schemes and deadlines depend on the scholarship.',te:'అనేక కేంద్ర, ఇతర స్కాలర్‌షిప్‌లకు అధికారిక వేదిక; పథకం, గడువులు స్కాలర్‌షిప్‌ను బట్టి మారుతాయి.'},eligibility:{en:['There is no single eligibility rule for NSP: each listed scholarship has its own class/course, institution, income, category and merit/means conditions.','Applicants must meet the selected scholarship\'s academic-year rules and submit through the correct portal window; some scholarships require fresh applications and others renewals.','Aadhaar/OTR, institute verification, bank-account requirements and other checks depend on the current scholarship notice.','Check the scheme-specific guideline and eligibility checker before applying; listing on NSP alone does not mean a student qualifies.'],te:['NSPలో ఒకే అర్హత నియమం ఉండదు; ప్రతి స్కాలర్‌షిప్‌కు తరగతి/కోర్సు, విద్యాసంస్థ, ఆదాయం, వర్గం, మెరిట్/ఆర్థిక ప్రమాణాలు వేర్వేరుగా ఉంటాయి.','దరఖాస్తుదారు ప్రస్తుత విద్యా సంవత్సరం నిబంధనలు పాటించి సరైన గడువులో దరఖాస్తు చేయాలి; కొన్ని కొత్త దరఖాస్తులు, మరికొన్ని రెన్యువల్‌లు.','ఆధార్/OTR, సంస్థ ధృవీకరణ, బ్యాంకు ఖాతా, ఇతర తనిఖీలు స్కాలర్‌షిప్ నోటీసుపై ఆధారపడతాయి.','దరఖాస్తు ముందు నిర్దిష్ట స్కాలర్‌షిప్ మార్గదర్శకాలు, అర్హత తనిఖీ చూడండి; NSPలో ఉండటం మాత్రమే అర్హతకు హామీ కాదు.']},documents:{en:['Student identity/Aadhaar details and photograph.','Admission/bonafide certificate, course details and marksheets.','Income and caste/category/disability/minority certificates where applicable.','Student bank passbook/account details as specified.','Domicile and institute verification records if required; follow the selected scholarship notice.'],te:['విద్యార్థి గుర్తింపు/ఆధార్ వివరాలు, ఫోటో.','అడ్మిషన్/బోనఫైడ్ సర్టిఫికెట్, కోర్సు వివరాలు, మార్కుల మెమోలు.','వర్తిస్తే ఆదాయ, కుల/వర్గ, దివ్యాంగత/మైనారిటీ ధృవపత్రాలు.','నిబంధనల ప్రకారం విద్యార్థి బ్యాంకు ఖాతా వివరాలు.','అవసరమైతే నివాస, సంస్థ ధృవీకరణ రికార్డులు; ఎంచుకున్న స్కాలర్‌షిప్ నోటీసును అనుసరించండి.']},steps:{en:['Search scholarships on the official portal.','Read the scheme guidelines and current application dates.'],te:['అధికారిక పోర్టల్‌లో స్కాలర్‌షిప్‌లను వెతకండి.','పథక మార్గదర్శకాలు, ప్రస్తుత దరఖాస్తు తేదీలను చదవండి.']},officialUrl:'https://scholarships.gov.in/',category:'education'},
{id:'pmjay',name:{en:'Ayushman Bharat – Pradhan Mantri Jan Arogya Yojana (AB PM-JAY)',te:'ఆయుష్మాన్ భారత్ – ప్రధాన మంత్రి జన్ ఆరోగ్య యోజన (AB PM-JAY)'},scope:'central',states:[],summary:{en:'Government health assurance programme for eligible beneficiaries; coverage and access should be checked through official channels.',te:'అర్హ లబ్ధిదారుల కోసం ప్రభుత్వ ఆరోగ్య భరోసా కార్యక్రమం; కవరేజ్, సేవల వివరాలను అధికారిక మార్గాల ద్వారా నిర్ధారించాలి.'},eligibility:{en:['Eligibility is based on the beneficiary databases and rules adopted for PM-JAY; not every household is automatically covered.','Check the household/member name using the official beneficiary eligibility service or an authorised Ayushman help desk.','Treatment is cashless only for eligible beneficiaries, covered packages and services at empanelled hospitals, subject to scheme rules.','State extensions, card issuance and accepted beneficiary records may differ; verify the current state implementation.'],te:['PM-JAYకు ఆమోదించిన లబ్ధిదారుల డేటాబేస్‌లు, నియమాల ఆధారంగా అర్హత నిర్ణయిస్తారు; ప్రతి కుటుంబం ఆటోమేటిక్‌గా కవర్ కాదు.','అధికారిక అర్హత సేవ లేదా అధీకృత ఆయుష్మాన్ సహాయ కేంద్రంలో కుటుంబం/సభ్యుని పేరు తనిఖీ చేయండి.','అర్హ లబ్ధిదారులకు, కవర్ చేసిన ప్యాకేజీలు/సేవలకు, అనుబంధ ఆసుపత్రుల్లో మాత్రమే నిబంధనలకు లోబడి నగదు రహిత చికిత్స ఉంటుంది.','రాష్ట్ర విస్తరణలు, కార్డు జారీ, ఆమోదిత లబ్ధిదారు రికార్డులు మారవచ్చు; ప్రస్తుత రాష్ట్ర అమలును నిర్ధారించండి.']},documents:{en:['Aadhaar or another accepted photo ID.','Ration/family card or record used to match eligible household, if requested.','Ayushman card or verified beneficiary record, if issued.','For treatment: medical reports, diagnosis/referral and hospital-requested records.'],te:['ఆధార్ లేదా ఆమోదిత ఫోటో గుర్తింపు పత్రం.','అడిగితే రేషన్/కుటుంబ కార్డు లేదా అర్హ కుటుంబాన్ని సరిపోల్చే రికార్డు.','జారీ చేసి ఉంటే ఆయుష్మాన్ కార్డు/ధృవీకరించిన లబ్ధిదారు రికార్డు.','చికిత్సకు వైద్య నివేదికలు, నిర్ధారణ/రిఫరల్, ఆసుపత్రి కోరే పత్రాలు.']},steps:{en:['Use the official PM-JAY website to check eligibility.','Confirm empanelled hospitals and current services.'],te:['అర్హత కోసం అధికారిక PM-JAY వెబ్‌సైట్‌ను ఉపయోగించండి.','అనుబంధ ఆసుపత్రులు, ప్రస్తుత సేవలను నిర్ధారించండి.']},officialUrl:'https://pmjay.gov.in/',category:'health'},
{id:'pmay-urban',name:{en:'Pradhan Mantri Awas Yojana – Urban (PMAY-U)',te:'ప్రధాన మంత్రి ఆవాస్ యోజన – అర్బన్ (PMAY-U)'},scope:'central',states:[],summary:{en:'Urban housing programme; current phase, eligibility and application route depend on the applicable guidelines and local authority.',te:'పట్టణ గృహవసతి కార్యక్రమం; ప్రస్తుత దశ, అర్హత, దరఖాస్తు విధానం వర్తించే మార్గదర్శకాలు, స్థానిక సంస్థపై ఆధారపడి ఉంటాయి.'},eligibility:{en:['PMAY-U 2.0 targets eligible urban households in EWS (annual family income up to ₹3 lakh), LIG (₹3–6 lakh) and MIG (₹6–9 lakh) categories, subject to the selected benefit vertical.','The family must not own a pucca house anywhere in India, subject to the detailed guidelines.','The applicant must meet the family definition and live in a covered urban area.','A household that already received housing assistance under a central government housing scheme may be ineligible; confirm the current vertical-specific rules and local application availability.'],te:['PMAY-U 2.0లో ఎంపిక చేసిన ప్రయోజన విభాగం నిబంధనలకు లోబడి EWS (కుటుంబ వార్షిక ఆదాయం ₹3 లక్షల వరకు), LIG (₹3–6 లక్షలు), MIG (₹6–9 లక్షలు) పట్టణ కుటుంబాలు లక్ష్యంగా ఉంటాయి.','వివరణాత్మక మార్గదర్శకాల ప్రకారం కుటుంబానికి భారతదేశంలో ఎక్కడా పక్కా ఇల్లు ఉండకూడదు.','దరఖాస్తుదారు కుటుంబ నిర్వచనం, కవర్ చేసే పట్టణ ప్రాంత నిబంధనలను పాటించాలి.','ఇప్పటికే కేంద్ర గృహ పథకం కింద సహాయం పొందిన కుటుంబం అర్హత కోల్పోవచ్చు; ప్రస్తుత విభాగ-నిర్దిష్ట నియమాలు, స్థానిక దరఖాస్తుల అందుబాటును నిర్ధారించండి.']},documents:{en:['Aadhaar/Aadhaar enrolment ID as permitted.','Income self-certificate/affidavit and salary slips/ITR where applicable.','Identity, address and nationality proof.','Bank passbook/account statement.','Declaration that the family owns no pucca house and has not received disallowed housing aid.','Property/land papers, valuation/construction estimate and category certificate if relevant to chosen vertical.'],te:['అనుమతించిన విధంగా ఆధార్/ఆధార్ నమోదు ఐడీ.','ఆదాయ స్వీయ ధృవీకరణ/అఫిడవిట్, వర్తిస్తే జీతపు స్లిప్‌లు/ITR.','గుర్తింపు, చిరునామా, జాతీయత ఆధారం.','బ్యాంకు పాస్‌బుక్/ఖాతా స్టేట్‌మెంట్.','పక్కా ఇల్లు లేదని, అనుమతించని గృహసహాయం పొందలేదని ప్రకటన.','ఎంచుకున్న విభాగానికి అవసరమైతే ఆస్తి/భూమి పత్రాలు, నిర్మాణ అంచనా, వర్గ ధృవపత్రం.']},steps:{en:['Read the current PMAY-U guidelines.','Contact the designated local authority for application availability.'],te:['ప్రస్తుత PMAY-U మార్గదర్శకాలను చదవండి.','దరఖాస్తుల అందుబాటు కోసం నియమిత స్థానిక సంస్థను సంప్రదించండి.']},officialUrl:'https://pmay-urban.gov.in/',category:'housing'},
{id:'pmay-g',name:{en:'Pradhan Mantri Awaas Yojana – Gramin (PMAY-G)',te:'ప్రధాన మంత్రి ఆవాస్ యోజన – గ్రామీణ (PMAY-G)'},scope:'central',states:[],summary:{en:'Rural housing assistance programme administered under official eligibility and beneficiary selection rules.',te:'అధికారిక అర్హత, లబ్ధిదారుల ఎంపిక నిబంధనల ప్రకారం అమలయ్యే గ్రామీణ గృహ సహాయ పథకం.'},eligibility:{en:['The programme is for eligible rural households identified through the applicable deprivation/beneficiary-selection process and official lists, not an open first-come application for every household.','Households meeting exclusion criteria or already owning a qualifying pucca house may be ineligible under the current rules.','Beneficiary identification and priority depend on official survey/list verification and local government checks.','Confirm the name/status in the current PMAY-G/Awaas+ list with the Gram Panchayat or block office.'],te:['వర్తించే వెనుకబాటుతనం/లబ్ధిదారుల ఎంపిక ప్రక్రియ, అధికారిక జాబితాల ద్వారా గుర్తించిన అర్హ గ్రామీణ కుటుంబాలకు ఈ పథకం వర్తిస్తుంది; ప్రతి ఒక్కరికీ ముందుగా దరఖాస్తు చేసే పథకం కాదు.','ప్రస్తుత నియమాల ప్రకారం మినహాయింపు ప్రమాణాలకు లోబడిన లేదా ఇప్పటికే అర్హమైన పక్కా ఇల్లు ఉన్న కుటుంబాలు అనర్హులు కావచ్చు.','లబ్ధిదారుల గుర్తింపు, ప్రాధాన్యత అధికారిక సర్వే/జాబితా ధృవీకరణ, స్థానిక ప్రభుత్వ తనిఖీలపై ఆధారపడి ఉంటాయి.','గ్రామ పంచాయతీ లేదా మండల కార్యాలయంలో ప్రస్తుత PMAY-G/Awaas+ జాబితాలో పేరు/స్థితిని నిర్ధారించండి.']},documents:{en:['Aadhaar/accepted identity details for household members.','Official beneficiary-list/Awaas+ or household reference, as applicable.','Bank account/passbook for payment.','Land/household records requested by Gram Panchayat.','Category certificate only where relevant to applicable rules.'],te:['కుటుంబ సభ్యుల ఆధార్/ఆమోదిత గుర్తింపు వివరాలు.','వర్తిస్తే అధికారిక లబ్ధిదారుల జాబితా/Awaas+ లేదా కుటుంబ రికార్డు.','చెల్లింపుల కోసం బ్యాంకు ఖాతా/పాస్‌బుక్.','గ్రామ పంచాయతీ కోరే భూమి/కుటుంబ రికార్డులు.','వర్తించే నిబంధనలకు అవసరమైతే మాత్రమే వర్గ ధృవపత్రం.']},steps:{en:['Check official PMAY-G information and beneficiary lists.','Contact the Gram Panchayat or block office for local guidance.'],te:['అధికారిక PMAY-G సమాచారం, లబ్ధిదారుల జాబితాలను చూడండి.','స్థానిక మార్గదర్శకత్వం కోసం గ్రామ పంచాయతీ లేదా మండల కార్యాలయాన్ని సంప్రదించండి.']},officialUrl:'https://pmayg.nic.in/',category:'housing'},
{id:'skill-india',name:{en:'Skill India / Pradhan Mantri Kaushal Vikas Yojana',te:'స్కిల్ ఇండియా / ప్రధాన మంత్రి కౌశల్ వికాస్ యోజన'},scope:'central',states:[],summary:{en:'Skills training and certification initiatives. Course availability and eligibility vary by programme and training centre.',te:'నైపుణ్య శిక్షణ, ధృవీకరణ కార్యక్రమాలు. కోర్సుల అందుబాటు, అర్హత కార్యక్రమం, శిక్షణ కేంద్రాన్ని బట్టి మారుతాయి.'},eligibility:{en:['Eligibility is course-specific: age, education, prior experience, residency and other requirements depend on the currently available training course and scheme component.','Applicants must enrol through an authorised training provider/centre and meet that course\'s entry criteria.','Assessment, certification, placement support and any stipend are subject to the specific programme and provider terms; employment is not guaranteed.','Verify the course and centre on the official Skill India/Skill India Digital portal before sharing documents or paying any fee.'],te:['అర్హత కోర్సును బట్టి మారుతుంది: వయస్సు, విద్య, అనుభవం, నివాసం ఇతర ప్రమాణాలు ప్రస్తుత కోర్సు/పథక విభాగంపై ఆధారపడతాయి.','అధీకృత శిక్షణ సంస్థ/కేంద్రం ద్వారా నమోదు చేసి, కోర్సు ప్రవేశ ప్రమాణాలను పాటించాలి.','మూల్యాంకనం, సర్టిఫికెట్, ఉద్యోగ సహాయం, స్టైపెండ్ ఉంటే అవి నిర్దిష్ట కార్యక్రమం/సంస్థ నిబంధనలకు లోబడి ఉంటాయి; ఉద్యోగం హామీ కాదు.','పత్రాలు ఇవ్వడానికి లేదా ఫీజు చెల్లించడానికి ముందు అధికారిక Skill India పోర్టల్‌లో కోర్సు, కేంద్రాన్ని నిర్ధారించండి.']},documents:{en:['Aadhaar/accepted identity proof and mobile number.','Age proof and photograph if required.','Education/qualification certificates for selected course.','Category, disability, income or residence proof only if applicable.','Bank details if stipend/benefit is offered; verify authorised centre checklist.'],te:['ఆధార్/ఆమోదిత గుర్తింపు, మొబైల్ నంబర్.','అవసరమైతే వయస్సు ఆధారం, ఫోటో.','ఎంచుకున్న కోర్సుకు విద్యార్హత ధృవపత్రాలు.','వర్తిస్తే మాత్రమే వర్గ/దివ్యాంగత/ఆదాయ/నివాస ఆధారం.','స్టైపెండ్ ఉంటే బ్యాంకు వివరాలు; అధీకృత కేంద్రం జాబితాను నిర్ధారించండి.']},steps:{en:['Search current training opportunities on official Skill India services.','Confirm course, centre, fees if any, and eligibility before enrolling.'],te:['అధికారిక స్కిల్ ఇండియా సేవల్లో ప్రస్తుత శిక్షణ అవకాశాలను వెతకండి.','నమోదుకు ముందు కోర్సు, కేంద్రం, ఉంటే ఫీజులు, అర్హతను నిర్ధారించండి.']},officialUrl:'https://www.skillindiadigital.gov.in/',category:'employment'},
{id:'nps',name:{en:'National Pension System (NPS)',te:'జాతీయ పెన్షన్ వ్యవస్థ (NPS)'},scope:'central',states:[],summary:{en:'Regulated retirement savings system with account types and rules set by the official NPS framework.',te:'అధికారిక NPS నిబంధనల ప్రకారం ఖాతా రకాలు, నియమాలు కలిగిన నియంత్రిత పదవీ విరమణ పొదుపు వ్యవస్థ.'},eligibility:{en:['NPS is a regulated retirement savings system; eligibility, contribution and withdrawal rules depend on the NPS account type and subscriber category.','Most individual All Citizen NPS accounts are available to eligible Indian citizens/NRIs within the current entry-age and KYC rules; special government/corporate variants have separate rules.','Tax treatment, investment returns and withdrawal/annuity outcomes depend on current regulations and are not guaranteed returns.','Check the current PFRDA/Protean/authorised-provider rules for age, KYC, exit and tax conditions before opening or withdrawing.'],te:['NPS నియంత్రిత పదవీ విరమణ పొదుపు వ్యవస్థ; ఖాతా రకం, చందాదారు వర్గాన్ని బట్టి అర్హత, చందా, ఉపసంహరణ నియమాలు మారుతాయి.','వ్యక్తిగత All Citizen NPS ఖాతాలు ప్రస్తుత ప్రవేశ వయస్సు, KYC నియమాలకు లోబడి అర్హ భారతీయులు/NRIలకు అందుబాటులో ఉంటాయి; ప్రభుత్వ/కార్పొరేట్ ఖాతాలకు వేర్వేరు నియమాలు ఉంటాయి.','పన్ను విధానం, పెట్టుబడి రాబడి, ఉపసంహరణ/యాన్యుటీ ఫలితాలు ప్రస్తుత నియమాలపై ఆధారపడి ఉంటాయి; రాబడి హామీ కాదు.','ఖాతా తెరవడానికి లేదా ఉపసంహరించడానికి ముందు PFRDA/అధీకృత సేవాదారు వద్ద వయస్సు, KYC, ఎగ్జిట్, పన్ను నియమాలు చూడండి.']},documents:{en:['PAN and accepted KYC/identity/address proof.','Date-of-birth proof, photograph and signature as requested.','Bank account details and nominee information.','Provider/CRA forms required for the selected NPS account type.'],te:['PAN, ఆమోదిత KYC/గుర్తింపు/చిరునామా పత్రం.','అడిగితే పుట్టిన తేదీ ఆధారం, ఫోటో, సంతకం.','బ్యాంకు ఖాతా, నామినీ వివరాలు.','ఎంచుకున్న NPS ఖాతాకు CRA/సేవాదారు కోరే ఫారాలు.']},steps:{en:['Read official NPS information and compare account options.','Use an authorised service provider to check onboarding requirements.'],te:['అధికారిక NPS సమాచారాన్ని చదివి ఖాతా ఎంపికలను పోల్చండి.','నమోదు అవసరాల కోసం అధీకృత సేవాదారుడిని సంప్రదించండి.']},officialUrl:'https://npstrust.org.in/',category:'social'},
{id:'atal-pension',name:{en:'Atal Pension Yojana (APY)',te:'అటల్ పెన్షన్ యోజన (APY)'},scope:'central',states:[],summary:{en:'Pension scheme available through participating banks and post offices, subject to current joining rules.',te:'ప్రస్తుత చేరిక నిబంధనలకు లోబడి పాల్గొనే బ్యాంకులు, పోస్టాఫీసుల ద్వారా అందుబాటులో ఉండే పెన్షన్ పథకం.'},eligibility:{en:['The scheme is designed for eligible bank/post-office savings-account holders who meet the current joining-age rules; verify the applicable entry age with the bank.','A savings account and consent for periodic auto-debit are required; contributions depend on joining age and selected pension amount.','Under current rules, a person who is or has been an income-tax payer may be ineligible to join from 1 October 2022; confirm the current official rule and exceptions.','Pension entitlement and spouse/nominee benefits follow APY rules; keep account active and contributions funded.'],te:['ప్రస్తుత చేరిక వయస్సు నియమాలను పాటించే అర్హ బ్యాంకు/పోస్టాఫీసు పొదుపు ఖాతాదారుల కోసం ఈ పథకం రూపొందించబడింది; వర్తించే ప్రవేశ వయస్సును బ్యాంకులో నిర్ధారించండి.','పొదుపు ఖాతా, నిరంతర ఆటో-డెబిట్ సమ్మతి అవసరం; చందా చేరిక వయస్సు, ఎంచుకున్న పెన్షన్ మొత్తంపై ఆధారపడి ఉంటుంది.','ప్రస్తుత నియమాల ప్రకారం 2022 అక్టోబర్ 1 నుంచి ఆదాయపు పన్ను చెల్లిస్తున్న లేదా గతంలో చెల్లించిన వ్యక్తి చేరడానికి అనర్హుడు కావచ్చు; అధికారిక నియమాలు/మినహాయింపులు నిర్ధారించండి.','పెన్షన్, జీవిత భాగస్వామి/నామినీ ప్రయోజనాలు APY నియమాల ప్రకారం ఉంటాయి; ఖాతా చురుకుగా ఉంచి చందాలు సమయానికి చెల్లించండి.']},documents:{en:['Savings bank/post-office account details.','Aadhaar/mobile for KYC if requested.','Spouse and nominee details, where applicable.','Signed APY registration and auto-debit mandate.'],te:['బ్యాంకు/పోస్టాఫీసు పొదుపు ఖాతా వివరాలు.','KYC కోసం అడిగితే ఆధార్/మొబైల్.','వర్తిస్తే జీవిత భాగస్వామి, నామినీ వివరాలు.','సంతకం చేసిన APY నమోదు, ఆటో-డెబిట్ మాండేట్.']},steps:{en:['Read the official APY details.','Contact a participating bank or post office to confirm enrolment eligibility.'],te:['అధికారిక APY వివరాలను చదవండి.','చేరిక అర్హతను నిర్ధారించడానికి పాల్గొనే బ్యాంకు లేదా పోస్టాఫీసును సంప్రదించండి.']},officialUrl:'https://www.npscra.nsdl.co.in/scheme-details.php',category:'social'},
{id:'stand-up-india',name:{en:'Stand-Up India',te:'స్టాండ్-అప్ ఇండియా'},scope:'central',states:[],summary:{en:'Credit support initiative designed to facilitate bank loans for eligible SC/ST and women entrepreneurs for greenfield enterprises; check current status and terms.',te:'అర్హ SC/ST, మహిళా వ్యాపారవేత్తల కొత్త వ్యాపారాలకు బ్యాంకు రుణాలను సులభతరం చేసే కార్యక్రమం; ప్రస్తుత స్థితి, నిబంధనలను చూడండి.'},eligibility:{en:['The scheme\'s original target group is at least one SC/ST borrower or one woman borrower per bank branch for a greenfield enterprise, subject to current scheme status and lender rules.','The borrower must be 18 or older; a non-individual enterprise generally needs at least 51% shareholding and controlling stake held by an eligible SC/ST person or woman.','The loan is for a greenfield venture in manufacturing, services, trading or eligible allied-agriculture activity; existing-business expansion may not qualify under original greenfield terms.','Availability, loan range, margin and current application route must be confirmed with the official portal/bank because programme rules or successor arrangements may change.'],te:['ప్రాథమిక పథకం ప్రకారం గ్రీన్‌ఫీల్డ్ వ్యాపారానికి ప్రతి బ్యాంకు శాఖ పరిధిలో కనీసం ఒక SC/ST రుణగ్రహీత లేదా ఒక మహిళా రుణగ్రహీత లక్ష్యంగా ఉంటారు; ప్రస్తుత స్థితి, బ్యాంకు నియమాలు వర్తిస్తాయి.','రుణగ్రహీతకు కనీసం 18 ఏళ్లు ఉండాలి; సంస్థ దరఖాస్తులో సాధారణంగా అర్హ SC/ST వ్యక్తి లేదా మహిళకు కనీసం 51% వాటా, నియంత్రణ ఉండాలి.','తయారీ, సేవలు, వ్యాపారం లేదా అర్హ వ్యవసాయ అనుబంధ కార్యకలాపాల్లో కొత్త వ్యాపారం కోసం రుణం; పాత వ్యాపార విస్తరణ అసలు గ్రీన్‌ఫీల్డ్ నియమాలకు సరిపోకపోవచ్చు.','పథక స్థితి/వారస కార్యక్రమాలు మారవచ్చునందున అందుబాటు, రుణ పరిమితి, మార్జిన్, దరఖాస్తు మార్గాన్ని అధికారిక పోర్టల్/బ్యాంకుతో నిర్ధారించండి.']},documents:{en:['Identity/address proof, PAN and photograph as requested by lender.','SC/ST certificate if applying under that eligibility category.','Enterprise registration and ownership/shareholding details.','Project report/business plan, quotations and estimated project cost.','Bank statements, existing loan details and margin-money proof if requested.'],te:['రుణదాత కోరే గుర్తింపు/చిరునామా పత్రం, PAN, ఫోటో.','SC/ST అర్హత కింద దరఖాస్తు చేస్తే కుల/తెగ ధృవపత్రం.','సంస్థ రిజిస్ట్రేషన్, యాజమాన్యం/షేర్‌హోల్డింగ్ వివరాలు.','ప్రాజెక్ట్ నివేదిక, వ్యాపార ప్రణాళిక, కొటేషన్లు, ఖర్చుల అంచనా.','అడిగితే బ్యాంకు స్టేట్‌మెంట్లు, రుణ వివరాలు, స్వంత వాటా ఆధారం.']},steps:{en:['Review the official Stand-Up India portal for current programme information.','Contact a participating bank to verify availability and terms.'],te:['ప్రస్తుత కార్యక్రమ సమాచారం కోసం అధికారిక స్టాండ్-అప్ ఇండియా పోర్టల్‌ను చూడండి.','అందుబాటు, నిబంధనలను నిర్ధారించడానికి పాల్గొనే బ్యాంకును సంప్రదించండి.']},officialUrl:'https://www.standupmitra.in/',category:'women'},
{id:'beti-bachao',name:{en:'Beti Bachao Beti Padhao',te:'బేటీ బచావో బేటీ పడావో'},scope:'central',states:[],summary:{en:'Government initiative promoting the value, protection and education of the girl child; it is not a universal direct-cash benefit.',te:'బాలికల విలువ, రక్షణ, విద్యను ప్రోత్సహించే ప్రభుత్వ కార్యక్రమం; ఇది అందరికీ నేరుగా నగదు ఇచ్చే పథకం కాదు.'},eligibility:{en:['Beti Bachao Beti Padhao is primarily a public-awareness and multi-agency programme, not a direct cash-transfer scheme with an individual beneficiary application.','It focuses on addressing gender-biased sex selection, improving the value and protection of the girl child, and supporting girls\' education and participation.','Any scholarship, health, protection or education benefit must be applied for under that separate service\'s own eligibility rules.','Do not pay an agent for a supposed BBBP cash benefit; confirm any linked benefit with the responsible department.'],te:['బేటీ బచావో బేటీ పడావో ప్రధానంగా ప్రజా అవగాహన, విభాగాల సమన్వయ కార్యక్రమం; వ్యక్తిగత నగదు బదిలీ దరఖాస్తు పథకం కాదు.','లింగ వివక్షతో జరిగే ఎంపికను అరికట్టడం, బాలికల విలువ/రక్షణ పెంపు, విద్య, భాగస్వామ్యాన్ని ప్రోత్సహించడం దీని లక్ష్యాలు.','స్కాలర్‌షిప్, ఆరోగ్యం, రక్షణ లేదా విద్యా ప్రయోజనానికి ఆ ప్రత్యేక సేవ అర్హత నియమాల ప్రకారం దరఖాస్తు చేయాలి.','BBBP పేరుతో నగదు ప్రయోజనం ఇస్తామని ఏజెంట్లకు డబ్బు చెల్లించవద్దు; అనుసంధాన ప్రయోజనాన్ని సంబంధిత శాఖతో నిర్ధారించండి.']},documents:{en:['This awareness/coordination programme has no single universal direct-benefit application checklist.','For a linked education, health or child-protection service, bring the identity, residence, school/medical and category records that service specifically requires.'],te:['ఈ అవగాహన/సమన్వయ కార్యక్రమానికి అందరికీ ఒకే ప్రత్యక్ష ప్రయోజన పత్రాల జాబితా లేదు.','అనుసంధాన విద్య/ఆరోగ్యం/బాలల రక్షణ సేవకు ఆ సేవ కోరే గుర్తింపు, నివాస, పాఠశాల/వైద్య, వర్గ పత్రాలు ఇవ్వండి.']},steps:{en:['Read official programme information.','Check local women and child development services for relevant support.'],te:['అధికారిక కార్యక్రమ సమాచారాన్ని చదవండి.','సంబంధిత సహాయం కోసం స్థానిక మహిళా, శిశు అభివృద్ధి సేవలను చూడండి.']},officialUrl:'https://wcd.gov.in/',category:'women'},
{id:'ujjwala',name:{en:'Pradhan Mantri Ujjwala Yojana (PMUY)',te:'ప్రధాన మంత్రి ఉజ్వల యోజన (PMUY)'},scope:'central',states:[],summary:{en:'LPG connection support for eligible households under current scheme rules and application windows.',te:'ప్రస్తుత పథక నిబంధనలు, దరఖాస్తు గడువుల ప్రకారం అర్హ కుటుంబాలకు LPG కనెక్షన్ సహాయం.'},eligibility:{en:['PMUY is intended for adult women from eligible poor households that do not already have an LPG connection in the household, subject to current category and documentation rules.','The household must meet the current beneficiary category/poor-household criteria and submit the prescribed declaration and KYC.','Only one LPG connection per eligible household is permitted under the scheme rules; household records are checked to prevent duplicate benefits.','Connection support/subsidy components and enrolment availability can change; check the official PMUY portal or LPG distributor.'],te:['ప్రస్తుత వర్గ, పత్రాల నియమాలకు లోబడి, కుటుంబంలో ఇప్పటికే LPG కనెక్షన్ లేని అర్హ పేద కుటుంబాల వయోజన మహిళల కోసం PMUY ఉంది.','కుటుంబం ప్రస్తుత లబ్ధిదారు వర్గం/పేద కుటుంబ ప్రమాణాలను పాటించి, నిర్దేశిత ప్రకటన, KYC సమర్పించాలి.','డూప్లికేట్ ప్రయోజనాలను నివారించేందుకు కుటుంబ రికార్డులు తనిఖీ చేస్తారు; పథక నియమాల ప్రకారం అర్హ కుటుంబానికి ఒకే LPG కనెక్షన్ అనుమతిస్తారు.','కనెక్షన్ సహాయం/సబ్సిడీ భాగాలు, నమోదు అందుబాటు మారవచ్చు; అధికారిక PMUY పోర్టల్ లేదా LPG డిస్ట్రిబ్యూటర్‌తో నిర్ధారించండి.']},documents:{en:['Completed PMUY application/KYC form.','Applicant Aadhaar and adult family members\' Aadhaar as required.','Ration card or state family-composition document; prescribed migrant self-declaration where permitted.','Address proof if required, applicant bank details/passbook.','Prescribed poor-household declaration and category proof where applicable.'],te:['పూర్తి చేసిన PMUY దరఖాస్తు/KYC ఫారం.','అవసరమైన దరఖాస్తుదారు, వయోజన కుటుంబ సభ్యుల ఆధార్.','రేషన్ కార్డు/రాష్ట్ర కుటుంబ పత్రం; అనుమతించిన చోట వలసదారుల స్వీయ ప్రకటన.','అవసరమైతే చిరునామా ఆధారం, బ్యాంకు పాస్‌బుక్/వివరాలు.','వర్తిస్తే నిర్దేశిత పేద కుటుంబ ప్రకటన, వర్గ ఆధారం.']},steps:{en:['Review the official PMUY eligibility rules.','Apply through the official process or an authorised LPG distributor if eligible.'],te:['అధికారిక PMUY అర్హత నిబంధనలను చూడండి.','అర్హులైతే అధికారిక విధానం లేదా అధీకృత LPG పంపిణీదారుని ద్వారా దరఖాస్తు చేయండి.']},officialUrl:'https://www.pmuy.gov.in/',category:'utilities'},
{id:'national-career-service',name:{en:'National Career Service (NCS)',te:'జాతీయ కెరీర్ సేవ (NCS)'},scope:'central',states:[],summary:{en:'Government career and employment services, including job search and career-related resources.',te:'ఉద్యోగాల అన్వేషణ, కెరీర్ సంబంధిత వనరులతో కూడిన ప్రభుత్వ కెరీర్, ఉపాధి సేవలు.'},eligibility:{en:['NCS is a job-matching and career-services portal, not a guarantee of employment or a universal cash-benefit scheme.','Jobseeker eligibility and required qualifications depend on each employer\'s vacancy; applicants must meet the advertised age, education, experience and other criteria.','Employers and service providers may have separate verification requirements; use the official portal and verify employer details.','NCS registration and services are free; be cautious of anyone demanding money for registration or a guaranteed job.'],te:['NCS ఉద్యోగ అనుసంధానం, కెరీర్ సేవల పోర్టల్; ఉద్యోగం లేదా సాధారణ నగదు ప్రయోజనానికి హామీ కాదు.','ఉద్యోగార్ధి అర్హత, అవసరమైన విద్యార్హతలు ప్రతి ఖాళీపై ఆధారపడతాయి; ప్రకటనలోని వయస్సు, విద్య, అనుభవ ప్రమాణాలను పాటించాలి.','యజమానులు/సేవాదారులకు వేర్వేరు ధృవీకరణలు ఉండవచ్చు; అధికారిక పోర్టల్ ఉపయోగించి యజమాని వివరాలు నిర్ధారించండి.','NCS నమోదు, సేవలు ఉచితం; నమోదు లేదా హామీ ఉద్యోగం కోసం డబ్బు అడిగేవారి పట్ల జాగ్రత్తగా ఉండండి.']},documents:{en:['Mobile number and email for registration.','Profile/identity and education/qualification details.','CV, experience and skill certificates if relevant.','For a vacancy, only documents named in the employer/recruitment notice.'],te:['నమోదుకు మొబైల్ నంబర్, ఇమెయిల్.','ప్రొఫైల్/గుర్తింపు, విద్యార్హత వివరాలు.','వర్తిస్తే CV, అనుభవ/నైపుణ్య ధృవపత్రాలు.','నిర్దిష్ట ఉద్యోగ నోటీసులో కోరిన పత్రాలనే సమర్పించండి.']},steps:{en:['Create or access a profile on the official NCS portal.','Search vacancies and verify employer details before responding.'],te:['అధికారిక NCS పోర్టల్‌లో ప్రొఫైల్ సృష్టించండి లేదా ప్రవేశించండి.','ఉద్యోగాలను వెతికి స్పందించే ముందు యజమాని వివరాలను నిర్ధారించండి.']},officialUrl:'https://www.ncs.gov.in/',category:'employment'},
{id:'sugamya-bharat',name:{en:'Accessible India Campaign (Sugamya Bharat Abhiyan)',te:'సుగమ్య భారత్ అభియాన్'},scope:'central',states:[],summary:{en:'Government initiative to improve accessibility in public spaces, transport and information for persons with disabilities.',te:'వికలాంగుల కోసం ప్రజా ప్రదేశాలు, రవాణా, సమాచారంలో అందుబాటును మెరుగుపరిచే ప్రభుత్వ కార్యక్రమం.'},eligibility:{en:['Sugamya Bharat Abhiyan is an accessibility initiative, not one universal cash benefit with a single eligibility threshold.','Access to a specific facility, accommodation, grievance process or service depends on the responsible public building, transport provider, website or department.','For disability-specific entitlements, use the separate service\'s rules and any disability certificate/UDID requirements.','Report accessibility issues through the responsible authority\'s official channel.'],te:['సుగమ్య భారత్ అభియాన్ అందుబాటు సౌకర్యాల కార్యక్రమం; ఒకే అర్హత పరిమితి ఉన్న నగదు ప్రయోజనం కాదు.','ప్రత్యేక సౌకర్యం, అనుకూలీకరణ, ఫిర్యాదు లేదా సేవ సంబంధిత ప్రభుత్వ భవనం, రవాణా సంస్థ, వెబ్‌సైట్ లేదా శాఖపై ఆధారపడి ఉంటుంది.','దివ్యాంగులకు సంబంధించిన ప్రత్యేక ప్రయోజనాల కోసం ఆ సేవ నియమాలు, అవసరమైతే దివ్యాంగత ధృవపత్రం/UDID నిబంధనలు అనుసరించాలి.','అందుబాటు సమస్యలను సంబంధిత అధికారిక మార్గంలో తెలియజేయండి.']},documents:{en:['No single universal checklist applies to every accessibility service.','For a specific request, provide that service\'s application, identity/contact details and disability certificate/supporting evidence only where required.'],te:['అన్ని అందుబాటు సేవలకు ఒకే సాధారణ పత్రాల జాబితా లేదు.','నిర్దిష్ట సేవ కోరితే దాని దరఖాస్తు, గుర్తింపు/సంప్రదింపు వివరాలు, అవసరమైతే దివ్యాంగత ధృవపత్రం ఇవ్వండి.']},steps:{en:['Review official disability affairs information.','Contact the responsible authority for a specific accessibility service or issue.'],te:['అధికారిక దివ్యాంగుల వ్యవహారాల సమాచారాన్ని చూడండి.','నిర్దిష్ట అందుబాటు సేవ లేదా సమస్య కోసం సంబంధిత అధికారిని సంప్రదించండి.']},officialUrl:'https://depwd.gov.in/',category:'social'},
{id:'digital-india',name:{en:'Digital India',te:'డిజిటల్ ఇండియా'},scope:'central',states:[],summary:{en:'Umbrella initiative supporting digital public infrastructure, online services and digital inclusion.',te:'డిజిటల్ ప్రజా మౌలిక సదుపాయాలు, ఆన్‌లైన్ సేవలు, డిజిటల్ సమగ్రతకు మద్దతు ఇచ్చే సమగ్ర కార్యక్రమం.'},eligibility:{en:['Digital India is an umbrella initiative covering many digital public services, not a single benefit with one eligibility rule.','Eligibility and documents are determined by the specific service being accessed (for example, a certificate, digital identity, benefit or online government application).','Use official government portals and follow that service\'s current identity, residency, income and category requirements.','Do not assume that Digital India itself provides a direct payment or universal entitlement.'],te:['డిజిటల్ ఇండియా అనేక డిజిటల్ ప్రజా సేవలను కలిపే సమగ్ర కార్యక్రమం; ఒకే అర్హత నియమం ఉన్న ప్రయోజనం కాదు.','అర్హత, పత్రాలు ఉపయోగించే నిర్దిష్ట సేవపై (ఉదా. సర్టిఫికెట్, డిజిటల్ గుర్తింపు, ప్రయోజనం, ఆన్‌లైన్ దరఖాస్తు) ఆధారపడి ఉంటాయి.','అధికారిక ప్రభుత్వ పోర్టల్ ఉపయోగించి ఆ సేవకు సంబంధించిన తాజా గుర్తింపు, నివాస, ఆదాయ, వర్గ నిబంధనలు అనుసరించండి.','డిజిటల్ ఇండియా స్వయంగా ప్రత్యక్ష చెల్లింపు లేదా అందరికీ హక్కు ఇస్తుందని భావించవద్దు.']},documents:{en:['This umbrella programme has no single application checklist for every service.','Use the identity, address, eligibility certificates and application records required by the specific linked government service.'],te:['ఈ సమగ్ర కార్యక్రమానికి ప్రతి సేవకు ఒకే దరఖాస్తు జాబితా లేదు.','సంబంధిత ప్రభుత్వ సేవ కోరే గుర్తింపు, చిరునామా, అర్హత ధృవపత్రాలు, దరఖాస్తు రికార్డులను ఉపయోగించండి.']},steps:{en:['Explore official Digital India initiatives.','Open the responsible service portal for current instructions.'],te:['అధికారిక డిజిటల్ ఇండియా ఉపక్రమాలను అన్వేషించండి.','ప్రస్తుత సూచనల కోసం సంబంధిత సేవా పోర్టల్‌ను తెరవండి.']},officialUrl:'https://www.digitalindia.gov.in/',category:'science'},
{id:'khelo-india',name:{en:'Khelo India',te:'ఖేలో ఇండియా'},scope:'central',states:[],summary:{en:'National initiative to support sports participation and development; specific opportunities depend on current programmes and selection criteria.',te:'క్రీడల భాగస్వామ్యం, అభివృద్ధికి మద్దతు ఇచ్చే జాతీయ కార్యక్రమం; అవకాశాలు ప్రస్తుత కార్యక్రమాలు, ఎంపిక ప్రమాణాలపై ఆధారపడతాయి.'},eligibility:{en:['Eligibility depends on the current Khelo India component: athlete identification, competition, scholarship or sports infrastructure programme.','Athlete selection may depend on age group, sport, performance/selection trials, recognised competition results and current guidelines.','Scholarship or athlete support is only for selected/approved beneficiaries and may require continued performance and compliance.','Check the current official notice for the sport, age category, dates, selection process and benefit conditions.'],te:['అర్హత ప్రస్తుత ఖేలో ఇండియా విభాగం—క్రీడాకారుల గుర్తింపు, పోటీ, స్కాలర్‌షిప్ లేదా క్రీడా మౌలిక సదుపాయాలు—పై ఆధారపడి ఉంటుంది.','క్రీడాకారుల ఎంపిక వయస్సు వర్గం, క్రీడ, ప్రదర్శన/ట్రయల్స్, గుర్తింపు పొందిన పోటీ ఫలితాలు, ప్రస్తుత మార్గదర్శకాలపై ఆధారపడి ఉండవచ్చు.','స్కాలర్‌షిప్/సహాయం ఎంపికైన లేదా ఆమోదిత లబ్ధిదారులకే; నిరంతర ప్రదర్శన, నిబంధనల పాటింపు అవసరం కావచ్చు.','క్రీడ, వయస్సు వర్గం, తేదీలు, ఎంపిక విధానం, ప్రయోజనాల కోసం ప్రస్తుత అధికారిక నోటీసును చూడండి.']},documents:{en:['Documents vary by competition, scholarship or athlete-support component.','The current notice may require age proof, ID, photograph, sports achievement certificates, medical/fitness certificate and bank details for approved benefits.'],te:['పత్రాలు పోటీ, స్కాలర్‌షిప్ లేదా క్రీడాకారుల సహాయ విభాగాన్ని బట్టి మారుతాయి.','ప్రస్తుత నోటీసు ప్రకారం వయస్సు ఆధారం, ID, ఫోటో, క్రీడా ధృవపత్రాలు, వైద్య/ఫిట్‌నెస్ సర్టిఫికెట్, ప్రయోజనం ఉంటే బ్యాంకు వివరాలు అడగవచ్చు.']},steps:{en:['Visit the official Khelo India website.','Check current initiatives, events and selection announcements.'],te:['అధికారిక ఖేలో ఇండియా వెబ్‌సైట్‌ను సందర్శించండి.','ప్రస్తుత ఉపక్రమాలు, ఈవెంట్లు, ఎంపిక ప్రకటనలను చూడండి.']},officialUrl:'https://kheloindia.gov.in/',category:'sports'},
{id:'parivahan',name:{en:'Parivahan Sewa',te:'పరివాహన్ సేవ'},scope:'central',states:[],summary:{en:'Government online services and information for driving licences, vehicle registration and transport-related processes.',te:'డ్రైవింగ్ లైసెన్స్‌లు, వాహన నమోదు, రవాణా ప్రక్రియల కోసం ప్రభుత్వ ఆన్‌లైన్ సేవలు, సమాచారం.'},eligibility:{en:['Parivahan is a portal for multiple transport services, not one scheme with a common eligibility rule.','A learner\'s/driving licence requires the applicable minimum age, learner/skill tests and documents under the Motor Vehicles rules.','Vehicle registration, permits, tax and other services have separate owner, vehicle, insurance, fitness and state-specific conditions.','Choose the exact service and state on the official portal; the portal listing itself does not mean every service is available to every applicant.'],te:['పరివాహన్ అనేక రవాణా సేవల పోర్టల్; ఒకే అర్హత నియమం ఉన్న పథకం కాదు.','లెర్నర్/డ్రైవింగ్ లైసెన్స్‌కు మోటారు వాహన నియమాల ప్రకారం వర్తించే కనీస వయస్సు, పరీక్షలు, పత్రాలు అవసరం.','వాహన రిజిస్ట్రేషన్, పర్మిట్, పన్ను, ఇతర సేవలకు యజమాని, వాహనం, బీమా, ఫిట్‌నెస్, రాష్ట్ర-నిర్దిష్ట షరతులు వేర్వేరుగా ఉంటాయి.','అధికారిక పోర్టల్‌లో ఖచ్చితమైన సేవ, రాష్ట్రాన్ని ఎంచుకోండి; పోర్టల్‌లో సేవ కనిపించడం మాత్రమే అందరికీ అర్హత ఉందని కాదు.']},documents:{en:['Checklist depends on selected service (learner/driving licence, registration, permit, etc.).','Keep application/reference number and required identity, address, age proof and photographs.','For vehicle services, relevant RC, insurance, PUC, tax/fee receipt and service-specific forms.','Check exact state/service checklist before visiting.'],te:['ఎంచుకున్న సేవపై పత్రాలు మారుతాయి.','అవసరమైన దరఖాస్తు నంబర్, గుర్తింపు/చిరునామా/వయస్సు ఆధారం, ఫోటోలు సిద్ధంగా ఉంచండి.','వాహన సేవలకు వర్తించే RC, బీమా, PUC, పన్ను/ఫీజు రసీదు, సేవా ఫారాలు.','వెళ్లే ముందు రాష్ట్రం/సేవ ఖచ్చితమైన జాబితాను చూడండి.']},steps:{en:['Select the relevant service on the official portal.','Follow the instructions for your state and application type.'],te:['అధికారిక పోర్టల్‌లో సంబంధిత సేవను ఎంచుకోండి.','మీ రాష్ట్రం, దరఖాస్తు రకానికి సంబంధించిన సూచనలను అనుసరించండి.']},officialUrl:'https://parivahan.gov.in/',category:'transport'},
{id:'incredible-india',name:{en:'Incredible India',te:'ఇన్‌క్రెడిబుల్ ఇండియా'},scope:'central',states:[],summary:{en:'Official tourism information and travel inspiration; this is an information portal rather than a general cash-benefit scheme.',te:'అధికారిక పర్యాటక సమాచారం, ప్రయాణ సూచనలు; ఇది సాధారణ నగదు ప్రయోజన పథకం కాదు.'},eligibility:{en:['Incredible India is a tourism information and promotion platform, not a general government cash-benefit scheme.','Access to a destination, protected area, monument or activity depends on its own ticketing, permit, age, nationality and safety rules.','Foreign visitors must follow applicable visa and entry requirements; protected-area permits may be required in specified locations.','Check the destination\'s official authority before travel for current access restrictions and permits.'],te:['ఇన్‌క్రెడిబుల్ ఇండియా పర్యాటక సమాచారం/ప్రచార వేదిక; సాధారణ నగదు ప్రయోజన పథకం కాదు.','ప్రదేశం, రక్షిత ప్రాంతం, స్మారకం లేదా కార్యకలాపానికి ప్రవేశం దాని టికెట్, పర్మిట్, వయస్సు, జాతీయత, భద్రత నియమాలపై ఆధారపడి ఉంటుంది.','విదేశీ సందర్శకులు వర్తించే వీసా/ప్రవేశ నిబంధనలు పాటించాలి; కొన్ని ప్రాంతాలకు ప్రత్యేక పర్మిట్ అవసరం కావచ్చు.','ప్రయాణానికి ముందు ప్రస్తుత ప్రవేశ పరిమితులు, పర్మిట్లను సంబంధిత అధికారిక సంస్థతో నిర్ధారించండి.']},documents:{en:['General travel information normally requires no scheme application documents.','For permits/protected areas/specific tourism services, carry identity, passport/visa and permit documents specified by the responsible authority.'],te:['సాధారణ ప్రయాణ సమాచారానికి పథక దరఖాస్తు పత్రాలు అవసరం ఉండవు.','పర్మిట్/రక్షిత ప్రాంతం/ప్రత్యేక పర్యాటక సేవకు సంబంధిత అధికారి కోరే గుర్తింపు, పాస్‌పోర్ట్/వీసా, పర్మిట్ పత్రాలు తీసుకెళ్లండి.']},steps:{en:['Browse official tourism information.','Verify travel, entry and permit rules with the relevant authority.'],te:['అధికారిక పర్యాటక సమాచారాన్ని చూడండి.','ప్రయాణం, ప్రవేశం, అనుమతి నిబంధనలను సంబంధిత అధికారితో నిర్ధారించండి.']},officialUrl:'https://www.incredibleindia.gov.in/',category:'tourism'},
{id:'swachh-bharat',name:{en:'Swachh Bharat Mission',te:'స్వచ్ఛ భారత్ మిషన్'},scope:'central',states:[],summary:{en:'National cleanliness and sanitation mission with rural and urban components; local benefits and services depend on the component and authority.',te:'గ్రామీణ, పట్టణ విభాగాలతో కూడిన జాతీయ పరిశుభ్రత, పారిశుధ్య కార్యక్రమం; స్థానిక ప్రయోజనాలు, సేవలు విభాగం, అధికారిపై ఆధారపడతాయి.'},eligibility:{en:['Eligibility depends on the active component: rural sanitation (SBM-G), urban sanitation (SBM-U), individual household toilets, community facilities or local-body projects.','Individual household assistance, where available, depends on local implementation, household eligibility and the applicable phase\'s rules; it is not automatically payable to every household.','Urban/rural local bodies may use different application, verification and construction-completion procedures.','Confirm the current component, location coverage, incentive amount and application route with the Gram Panchayat/urban local body.'],te:['ప్రస్తుత విభాగం—గ్రామీణ పారిశుధ్యం (SBM-G), పట్టణ పారిశుధ్యం (SBM-U), వ్యక్తిగత మరుగుదొడ్డి, సామూహిక సదుపాయం లేదా స్థానిక సంస్థ ప్రాజెక్ట్—పై అర్హత ఆధారపడి ఉంటుంది.','అందుబాటులో ఉన్న చోట వ్యక్తిగత ఇంటి సహాయం స్థానిక అమలు, కుటుంబ అర్హత, ప్రస్తుత దశ నియమాలపై ఆధారపడి ఉంటుంది; ప్రతి కుటుంబానికి ఆటోమేటిక్‌గా చెల్లించరు.','పట్టణ/గ్రామీణ స్థానిక సంస్థల్లో దరఖాస్తు, ధృవీకరణ, నిర్మాణ పూర్తిచేసే విధానాలు వేరుగా ఉండవచ్చు.','ప్రస్తుత విభాగం, ప్రాంత కవరేజ్, ప్రోత్సాహక మొత్తం, దరఖాస్తు మార్గాన్ని గ్రామ పంచాయతీ/పట్టణ సంస్థతో నిర్ధారించండి.']},documents:{en:['Documents depend on household toilet, community facility or local-body component.','For household benefits, keep identity/address, household/ration-card and bank details.','Construction photographs/geotag evidence or other local verification records if required.','Confirm the active component and list with Gram Panchayat/urban local body.'],te:['పత్రాలు ఇంటి మరుగుదొడ్డి, సామూహిక సదుపాయం లేదా స్థానిక సంస్థ విభాగంపై ఆధారపడి ఉంటాయి.','ఇంటి ప్రయోజనాలకు గుర్తింపు/చిరునామా, కుటుంబ/రేషన్ కార్డు, బ్యాంకు వివరాలు సిద్ధంగా ఉంచండి.','అవసరమైతే నిర్మాణ ఫోటోలు/జియోట్యాగ్ లేదా స్థానిక ధృవీకరణ రికార్డులు.','గ్రామ పంచాయతీ/పట్టణ సంస్థతో ప్రస్తుత జాబితాను నిర్ధారించండి.']},steps:{en:['Identify the relevant rural or urban service.','Contact the local authority or official portal for current guidance.'],te:['సంబంధిత గ్రామీణ లేదా పట్టణ సేవను గుర్తించండి.','ప్రస్తుత మార్గదర్శకత్వం కోసం స్థానిక అధికారిని లేదా అధికారిక పోర్టల్‌ను సంప్రదించండి.']},officialUrl:'https://swachhbharatmission.ddws.gov.in/',category:'utilities'},

{id:'ts-mahalakshmi',name:{en:'Maha Lakshmi Scheme (Telangana)',te:'మహాలక్ష్మి పథకం (తెలంగాణ)'},scope:'state',states:['Telangana'],summary:{en:'Telangana government initiative covering women-focused support, subsidised LPG and free bus travel. Check current operational rules and application routes on official state channels.',te:'మహిళలకు సహాయం, సబ్సిడీ LPG, ఉచిత బస్సు ప్రయాణం వంటి అంశాలతో తెలంగాణ ప్రభుత్వ కార్యక్రమం. ప్రస్తుత అమలు నిబంధనలు, దరఖాస్తు విధానాలను అధికారిక రాష్ట్ర మార్గాల్లో చూడండి.'},eligibility:{en:['Telangana’s state portal describes Maha Lakshmi as including ₹2,500 assistance for eligible women who are heads of their families, LPG cylinders at ₹500, and free TSRTC bus travel. Each benefit has separate rules; verify current beneficiary status and operational conditions with the responsible department or TSRTC.'],te:['ప్రతి ప్రయోజనానికి వేర్వేరు అర్హత, అమలు నిబంధనలు ఉంటాయి; ప్రస్తుత వివరాలను తెలంగాణ ప్రభుత్వం లేదా సంబంధిత శాఖతో నిర్ధారించండి.']},documents:{en:['For household assistance: Aadhaar, Telangana residence proof, ration/food-security card, family/income details and bank account as required.','For LPG benefit: domestic LPG consumer/connection record and household/Aadhaar/bank linkage if required.','For free TSRTC travel: valid ID accepted by current travel rules.','The benefits are separate and may have different requirements.'],te:['కుటుంబ సహాయానికి: ఆధార్, తెలంగాణ నివాస ఆధారం, రేషన్/ఆహార భద్రత కార్డు, కుటుంబ/ఆదాయ, బ్యాంకు వివరాలు — ప్రస్తుత దరఖాస్తు కోరిన మేరకు.','LPG కోసం: దేశీయ LPG వినియోగదారు/కనెక్షన్ రికార్డు, అవసరమైన కుటుంబ/ఆధార్/బ్యాంకు అనుసంధానం.','ఉచిత TSRTC ప్రయాణానికి ప్రస్తుత నియమాలు అంగీకరించే ID.','ప్రయోజనాలు వేర్వేరు; పత్రాలు కూడా వేర్వేరుగా ఉండవచ్చు.']},steps:{en:['Read the Telangana Government Initiatives page.','Confirm current availability, eligibility and application steps with the responsible department.'],te:['తెలంగాణ ప్రభుత్వ పథకాల పేజీని చూడండి.','ప్రస్తుత అందుబాటు, అర్హత, దరఖాస్తు దశలను సంబంధిత శాఖతో నిర్ధారించండి.']},officialUrl:'https://www.telangana.gov.in/government-initiatives/',category:'women'},
{id:'ts-cheyutha',name:{en:'Cheyutha / Rajiv Aarogyasri (Telangana)',te:'చేయూత / రాజీవ్ ఆరోగ్యశ్రీ (తెలంగాణ)'},scope:'state',states:['Telangana'],summary:{en:'Telangana health-care support initiative associated with Rajiv Aarogyasri. Confirm current coverage, beneficiary rules and empanelled hospitals through official channels.',te:'రాజీవ్ ఆరోగ్యశ్రీకి సంబంధించిన తెలంగాణ ఆరోగ్య సహాయ కార్యక్రమం. ప్రస్తుత కవరేజ్, లబ్ధిదారుల నిబంధనలు, అనుబంధ ఆసుపత్రులను అధికారిక మార్గాల్లో నిర్ధారించండి.'},eligibility:{en:['Telangana’s government portal describes Cheyutha under Rajiv Aarogyasri as health coverage up to ₹10 lakh per family for economically backward families. Eligibility and treatment depend on beneficiary records, covered packages and empanelled hospitals; confirm these before treatment.'],te:['కవరేజ్, అర్హత ప్రస్తుత రాష్ట్ర నిబంధనలు, లబ్ధిదారుల రికార్డులపై ఆధారపడి ఉంటాయి.']},documents:{en:['White ration/food-security card or household/beneficiary record used to establish eligibility.','Aadhaar or other accepted ID.','For treatment: medical reports, diagnosis and referral papers.','Carry beneficiary card/verified record and any papers requested by the empanelled hospital help desk.'],te:['తెల్ల రేషన్/ఆహార భద్రత కార్డు లేదా అర్హత నిర్ధారణకు కుటుంబ/లబ్ధిదారు రికార్డు.','ఆధార్ లేదా ఆమోదిత గుర్తింపు పత్రం.','చికిత్సకు వైద్య నివేదికలు, నిర్ధారణ, రిఫరల్ పత్రాలు.','ఆసుపత్రి సహాయ కేంద్రం కోరే పత్రాలు, లబ్ధిదారు కార్డు ఉంటే తీసుకెళ్లండి.']},steps:{en:['Visit the official Rajiv Aarogyasri portal.','Check beneficiary status, covered services and participating hospitals.'],te:['అధికారిక రాజీవ్ ఆరోగ్యశ్రీ పోర్టల్‌ను సందర్శించండి.','లబ్ధిదారుల స్థితి, కవర్ చేసే సేవలు, పాల్గొనే ఆసుపత్రులను చూడండి.']},officialUrl:'https://rajivaarogyasri.telangana.gov.in/',category:'health'},
{id:'ts-gruha-jyothi',name:{en:'Gruha Jyothi (Telangana)',te:'గృహ జ్యోతి (తెలంగాణ)'},scope:'state',states:['Telangana'],summary:{en:'Telangana household electricity-support scheme described by the state portal. Confirm current eligibility, application status and billing rules with official services.',te:'తెలంగాణ రాష్ట్ర పోర్టల్‌లో వివరించిన గృహ విద్యుత్ సహాయ పథకం. ప్రస్తుత అర్హత, దరఖాస్తు స్థితి, బిల్లింగ్ నియమాలను అధికారిక సేవల ద్వారా నిర్ధారించండి.'},eligibility:{en:['Covers up to 200 units of domestic electricity per month for one service connection per eligible household. The official order requires application through Praja Palana or an approved channel, a valid Food Security/white ration card linked with Aadhaar, and a domestic service-connection number. Consumption above 200 units is billed at the applicable tariff.'],te:['అర్హత, వినియోగ పరిమితులు ప్రస్తుత అధికారిక మార్గదర్శకాలు, రికార్డులకు లోబడి ఉంటాయి.']},documents:{en:['Domestic electricity service-connection number and latest bill.','Aadhaar and valid white ration/food-security card, linked as currently required.','Praja Palana/approved-channel application acknowledgement if available.','Check name/address/connection match with DISCOM or service centre.'],te:['ఇంటి విద్యుత్ కనెక్షన్ నంబర్, తాజా బిల్లు.','ఆధార్, ప్రస్తుత విధానం కోరే తెల్ల రేషన్/ఆహార భద్రత కార్డు అనుసంధానం.','ఉంటే ప్రజాపాలన/ఆమోదిత మార్గం దరఖాస్తు రసీదు.','పేరు/చిరునామా/కనెక్షన్ వివరాలను DISCOMతో సరిపోల్చండి.']},steps:{en:['Read the state government description.','Confirm your household record and current billing treatment with the responsible department.'],te:['రాష్ట్ర ప్రభుత్వ వివరణను చదవండి.','మీ కుటుంబ రికార్డు, ప్రస్తుత బిల్లింగ్ విధానాన్ని సంబంధిత శాఖతో నిర్ధారించండి.']},officialUrl:'https://www.telangana.gov.in/government-initiatives/',category:'utilities'},
{id:'ts-e-pass',name:{en:'Telangana ePASS Scholarships',te:'తెలంగాణ ePASS స్కాలర్‌షిప్‌లు'},scope:'state',states:['Telangana'],summary:{en:'Telangana scholarship portal for eligible student support programmes. Scholarship types, eligibility and deadlines vary by category and academic year.',te:'అర్హ విద్యార్థుల సహాయ కార్యక్రమాల కోసం తెలంగాణ స్కాలర్‌షిప్ పోర్టల్. స్కాలర్‌షిప్ రకాలు, అర్హత, గడువులు వర్గం, విద్యా సంవత్సరాన్ని బట్టి మారుతాయి.'},eligibility:{en:['The ePASS portal lists income ceilings by category: SC up to ₹2.5 lakh/year; ST up to ₹2 lakh; BC/EBC/minority rural up to ₹1.5 lakh and urban up to ₹2 lakh; disabled-welfare students’ parental income up to ₹1 lakh. Renewal students generally need 75% attendance each quarter and promotion. Course, admission-type and category exclusions apply; check the current academic-year notice.'],te:['కోర్సు, వర్గం, ఆదాయం, విద్యాసంస్థ ప్రమాణాల కోసం ప్రస్తుత స్కాలర్‌షిప్ నోటిఫికేషన్‌ను చూడండి.']},documents:{en:['Student identity/Aadhaar and photograph as required.','Applicable caste/community and income certificates.','Bonafide/admission certificate, course details, previous marksheets and attendance records.','Student bank account/passbook and Aadhaar linkage if required for DBT.','Family/category records and institute verification details as applicable; follow current academic-year checklist.'],te:['విద్యార్థి ఆధార్/గుర్తింపు, ఫోటో.','వర్తించే కుల/సమాజ, ఆదాయ ధృవపత్రాలు.','బోనఫైడ్/అడ్మిషన్, కోర్సు వివరాలు, మార్కుల మెమోలు, హాజరు రికార్డులు.','DBT అవసరమైతే విద్యార్థి బ్యాంకు వివరాలు, ఆధార్ అనుసంధానం.','వర్తించే కుటుంబ/వర్గ రికార్డులు, సంస్థ ధృవీకరణ; ప్రస్తుత విద్యా సంవత్సరం జాబితాను అనుసరించండి.']},steps:{en:['Open Telangana ePASS.','Choose the relevant scholarship and read the current academic-year notification.'],te:['తెలంగాణ ePASS తెరవండి.','సంబంధిత స్కాలర్‌షిప్‌ను ఎంచుకుని ప్రస్తుత విద్యా సంవత్సరం నోటిఫికేషన్‌ను చదవండి.']},officialUrl:'https://telanganaepass.cgg.gov.in/',category:'education'},
{id:'ts-aasara',name:{en:'Aasara Social Security Pensions (Telangana)',te:'ఆసరా సామాజిక భద్రత పెన్షన్లు (తెలంగాణ)'},scope:'state',states:['Telangana'],summary:{en:'Telangana social-security pension programme. Current eligible categories, application routes and payment status should be confirmed through the official portal.',te:'తెలంగాణ సామాజిక భద్రత పెన్షన్ కార్యక్రమం. ప్రస్తుత అర్హ వర్గాలు, దరఖాస్తు విధానం, చెల్లింపు స్థితిని అధికారిక పోర్టల్ ద్వారా నిర్ధారించండి.'},eligibility:{en:['The official portal lists multiple pension categories with different criteria. Examples: old-age pension from age 60; weaver, toddy-tapper and fisherman pensions generally from age 50; widow pension from age 18; disability pension with at least 40% disability and no age limit. Common conditions include BPL/white ration-card status, local residence and not receiving another pension. Exclusions and category rules apply; confirm current orders locally.'],te:['అర్హత ప్రస్తుత రాష్ట్ర నిబంధనలు, లబ్ధిదారుల వర్గంపై ఆధారపడి ఉంటుంది.']},documents:{en:['Aadhaar/accepted ID and photograph.','White ration/food-security card or BPL/family record as required.','Age proof for age-based pension; death certificate for widow category where required.','Disability certificate/UDID and percentage for disability category.','Occupation/category proof, residence and bank/post-office details if requested.'],te:['ఆధార్/ఆమోదిత ID, ఫోటో.','అవసరమైన తెల్ల రేషన్/ఆహార భద్రత కార్డు లేదా BPL/కుటుంబ రికార్డు.','వయస్సు ఆధారం; విధవ వర్గానికి అవసరమైతే మరణ ధృవపత్రం.','దివ్యాంగత వర్గానికి శాతం/UDIDతో ధృవపత్రం.','అవసరమైతే వృత్తి/వర్గ, నివాస, బ్యాంకు/పోస్టాఫీసు వివరాలు.']},steps:{en:['Visit the official Aasara portal.','Check the relevant pension category and contact the responsible local office for application guidance.'],te:['అధికారిక ఆసరా పోర్టల్‌ను సందర్శించండి.','సంబంధిత పెన్షన్ వర్గాన్ని చూసి దరఖాస్తు మార్గదర్శకత్వం కోసం స్థానిక కార్యాలయాన్ని సంప్రదించండి.']},officialUrl:'https://www.aasara.telangana.gov.in/',category:'social'},

{id:'ap-ntr-bharosa',name:{en:'NTR Bharosa Social Security Pensions (Andhra Pradesh)',te:'ఎన్‌టీఆర్ భరోసా సామాజిక భద్రత పెన్షన్లు (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'Andhra Pradesh pension support for eligible older people, widows, persons with disabilities and other covered groups. Check the current category rules and application process on the official portal.',te:'అర్హ వృద్ధులు, విధవలు, దివ్యాంగులు మరియు ఇతర అర్హ వర్గాల కోసం ఆంధ్రప్రదేశ్ పెన్షన్ సహాయం. ప్రస్తుత వర్గాల నిబంధనలు, దరఖాస్తు విధానాన్ని అధికారిక పోర్టల్‌లో చూడండి.'},eligibility:{en:['The official portal lists a white ration card/BPL status, local district residence and not receiving another pension as common conditions. Category examples include old-age pension from 60, weaver pension from 50, widow pension from 18 and disability pension with at least 40% disability. Exclusions include government/PSU employees and pensioners, income-tax payers, car owners and some larger landholders, subject to exceptions. Confirm the category-specific rules and current orders.'],te:['పెన్షన్ వర్గం, ప్రస్తుత రాష్ట్ర నిబంధనలను బట్టి అర్హత మారుతుంది. అధికారిక పోర్టల్ లేదా స్థానిక సచివాలయంలో మీ వివరాలను నిర్ధారించండి.']},documents:{en:['Aadhaar/accepted ID and photograph.','White ration card/BPL and residence/family details as required.','Age proof for old-age/occupation pension; death certificate for widow pension if required.','Disability certificate/UDID and percentage for disability pension.','Occupation/category proof and bank details where applicable.'],te:['ఆధార్/ఆమోదిత ID, ఫోటో.','అవసరమైన తెల్ల రేషన్/BPL, నివాస/కుటుంబ వివరాలు.','వృద్ధాప్య/వృత్తి పెన్షన్‌కు వయస్సు ఆధారం; విధవ వర్గానికి అవసరమైతే మరణ ధృవపత్రం.','దివ్యాంగ పెన్షన్‌కు శాతం/UDIDతో ధృవపత్రం.','వర్తిస్తే వృత్తి/వర్గ, బ్యాంకు వివరాలు.']},steps:{en:['Open the official NTR Bharosa portal.','Check pension category, eligibility and application guidance with your village/ward secretariat.'],te:['అధికారిక ఎన్‌టీఆర్ భరోసా పోర్టల్‌ను తెరవండి.','పెన్షన్ వర్గం, అర్హత, దరఖాస్తు సూచనలను గ్రామ/వార్డు సచివాలయంలో తెలుసుకోండి.']},officialUrl:'https://sspensions.ap.gov.in/SSP/Home/Index',category:'social'},
{id:'ap-ntr-vaidya-seva',name:{en:'Dr. NTR Vaidya Seva (Andhra Pradesh)',te:'డా. ఎన్‌టీఆర్ వైద్య సేవ (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'Andhra Pradesh health-care scheme for eligible beneficiaries. Confirm current coverage, eligibility and participating hospitals through the state health department.',te:'అర్హ లబ్ధిదారుల కోసం ఆంధ్రప్రదేశ్ ఆరోగ్య సేవా పథకం. ప్రస్తుత కవరేజ్, అర్హత, పాల్గొనే ఆసుపత్రులను రాష్ట్ర ఆరోగ్య శాఖ ద్వారా నిర్ధారించండి.'},eligibility:{en:['The AP health department describes beneficiaries as eligible BPL families listed in the Civil Supplies database with white ration cards and Aadhaar linkage. Listed treatments are cashless at network hospitals under current package rules; confirm beneficiary status, treatment coverage and hospital participation with the official trust.'],te:['లబ్ధిదారుల నిబంధనలు, కవర్ చేసే సేవలను ప్రస్తుత అధికారిక మార్గదర్శకాలతో చూడాలి.']},documents:{en:['White ration card/eligible family record in Civil Supplies database, as applicable.','Aadhaar or other accepted ID for beneficiary matching.','Health card/verified beneficiary record if issued.','For treatment: medical reports, diagnosis/referral and hospital-requested documents.'],te:['సివిల్ సప్లైస్ డేటాబేస్‌లోని తెల్ల రేషన్/అర్హ కుటుంబ రికార్డు, వర్తించే మేరకు.','లబ్ధిదారు సరిపోలికకు ఆధార్/ఆమోదిత ID.','జారీ చేసి ఉంటే ఆరోగ్య కార్డు/ధృవీకరించిన లబ్ధిదారు రికార్డు.','చికిత్సకు వైద్య నివేదికలు, నిర్ధారణ/రిఫరల్, ఆసుపత్రి కోరే పత్రాలు.']},steps:{en:['Read the state health department information.','Confirm eligibility and covered treatment at an authorised help desk or hospital.'],te:['రాష్ట్ర ఆరోగ్య శాఖ సమాచారాన్ని చదవండి.','అధీకృత సహాయ కేంద్రం లేదా ఆసుపత్రిలో అర్హత, చికిత్స కవరేజీని నిర్ధారించండి.']},officialUrl:'https://hmfw.ap.gov.in/ntr-aarogyaseva-org.aspx',category:'health'},
{id:'ap-thalliki-vandanam',name:{en:'Talliki Vandanam (Andhra Pradesh)',te:'తల్లికి వందనం (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'State education-support initiative for eligible mothers/guardians of school-going children. Check current academic-year conditions and payment status through official channels.',te:'పాఠశాలకు వెళ్లే పిల్లల అర్హ తల్లులు/సంరక్షకుల కోసం రాష్ట్ర విద్యా సహాయ కార్యక్రమం. ప్రస్తుత విద్యా సంవత్సర నిబంధనలు, చెల్లింపు స్థితిని అధికారిక మార్గాల్లో చూడండి.'},eligibility:{en:['Eligibility depends on the current Andhra Pradesh government order and academic-year implementation; check the current school-enrolment and attendance requirements.','The benefit is linked to eligible school-going children and the eligible mother/guardian/household under the current rules; not every student automatically qualifies.','Household, income/category, government-employee/taxpayer or other exclusions may apply as specified in the current order; do not rely on older announcements.','Verify student and guardian records with the school and village/ward secretariat before assuming payment eligibility.'],te:['ప్రస్తుత ఆంధ్రప్రదేశ్ ప్రభుత్వ ఉత్తర్వు, విద్యా సంవత్సరం అమలుపై అర్హత ఆధారపడి ఉంటుంది; నమోదు, హాజరు అవసరాలను చూడండి.','ప్రస్తుత నియమాల ప్రకారం అర్హ పాఠశాల పిల్లలు, తల్లి/సంరక్షకురాలు/కుటుంబానికి ప్రయోజనం అనుసంధానమవుతుంది; ప్రతి విద్యార్థికి ఆటోమేటిక్‌గా అర్హత ఉండదు.','ప్రస్తుత ఉత్తర్వులో పేర్కొన్న కుటుంబ, ఆదాయ/వర్గ, ప్రభుత్వ ఉద్యోగి/పన్ను చెల్లింపుదారు లేదా ఇతర మినహాయింపులు వర్తించవచ్చు; పాత ప్రకటనలపై ఆధారపడవద్దు.','చెల్లింపు అర్హత అనుకునే ముందు పాఠశాల, గ్రామ/వార్డు సచివాలయంలో విద్యార్థి, సంరక్షకురాలి వివరాలు నిర్ధారించండి.']},documents:{en:['Student identity/Aadhaar and school admission/UDISE details.','Mother/guardian identity and household/ration-card records as required by current order.','Eligible mother\'s/guardian\'s bank account details and DBT linkage if required.','School enrolment/attendance confirmation and any specifically required income/residence/category proof.','Confirm the current-year checklist with school or village/ward secretariat.'],te:['విద్యార్థి గుర్తింపు/ఆధార్, పాఠశాల అడ్మిషన్/UDISE వివరాలు.','ప్రస్తుత ఉత్తర్వు కోరే తల్లి/సంరక్షకురాలి గుర్తింపు, కుటుంబ/రేషన్ కార్డు.','అర్హ తల్లి/సంరక్షకురాలి బ్యాంకు వివరాలు, అవసరమైన DBT అనుసంధానం.','పాఠశాల నమోదు/హాజరు, ప్రస్తుత సంవత్సరం ప్రత్యేకంగా కోరే ఆదాయ/నివాస/వర్గ పత్రాలు.','పాఠశాల/గ్రామ-వార్డు సచివాలయంలో ప్రస్తుత జాబితాను నిర్ధారించండి.']},steps:{en:['Check the Andhra Pradesh government scheme information.','Confirm your child’s records and current-year eligibility through the school or village/ward secretariat.'],te:['ఆంధ్రప్రదేశ్ ప్రభుత్వ పథక సమాచారాన్ని చూడండి.','పాఠశాల లేదా గ్రామ/వార్డు సచివాలయం ద్వారా పిల్లల రికార్డులు, ప్రస్తుత సంవత్సరం అర్హతను నిర్ధారించండి.']},officialUrl:'https://apcfss.in/',category:'education'},
{id:'ap-annadata-sukhibhava',name:{en:'Annadata Sukhibhava (Andhra Pradesh)',te:'అన్నదాత సుఖీభవ (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'Farmer-support programme in Andhra Pradesh, coordinated with applicable central assistance where relevant. Check beneficiary status, land records and current instalment information on official state channels.',te:'ఆంధ్రప్రదేశ్ రైతు సహాయ కార్యక్రమం; వర్తించే చోట కేంద్ర సహాయంతో సమన్వయం ఉంటుంది. లబ్ధిదారుల స్థితి, భూమి రికార్డులు, ప్రస్తుత విడత వివరాలను అధికారిక రాష్ట్ర మార్గాల్లో చూడండి.'},eligibility:{en:['Eligibility is governed by the current Andhra Pradesh farmer-support order and beneficiary database; the name alone does not establish entitlement.','Landholding/cultivation records, farmer registration and bank/Aadhaar payment validation may be used to verify beneficiaries.','Tenant farmers, landless cultivators, joint land records and exclusions must be checked against the current state rules; do not assume all cultivators are included.','Check beneficiary status and any PM-KISAN linkage using official state agriculture channels before relying on an instalment or amount.'],te:['ప్రస్తుత ఆంధ్రప్రదేశ్ రైతు సహాయ ఉత్తర్వు, లబ్ధిదారుల డేటాబేస్ ఆధారంగా అర్హత నిర్ణయిస్తారు; పథకం పేరు మాత్రమే అర్హతను నిర్ధారించదు.','లబ్ధిదారుల ధృవీకరణకు భూమి/సాగు రికార్డులు, రైతు నమోదు, బ్యాంకు/ఆధార్ చెల్లింపు తనిఖీలు ఉపయోగించవచ్చు.','కౌలు రైతులు, భూమిలేని సాగుదారులు, ఉమ్మడి భూ రికార్డులు, మినహాయింపులను ప్రస్తుత రాష్ట్ర నియమాలతో తనిఖీ చేయాలి; అందరు సాగుదారులు అర్హులని భావించవద్దు.','వాయిదా/మొత్తంపై ఆధారపడే ముందు అధికారిక రాష్ట్ర వ్యవసాయ మార్గాల ద్వారా లబ్ధిదారుడి స్థితి, PM-KISAN అనుసంధానాన్ని చూడండి.']},documents:{en:['Aadhaar and active mobile number.','Land ownership/cultivation records and farmer details in agriculture records.','Bank passbook/account and Aadhaar/DBT status if required.','PM-KISAN status where state assistance is linked to central records.','Tenant/sharecropper proof only if current state rules permit and request it.'],te:['ఆధార్, క్రియాశీల మొబైల్ నంబర్.','వ్యవసాయ శాఖ రికార్డులలోని భూమి/సాగు, రైతు వివరాలు.','అవసరమైతే బ్యాంకు పాస్‌బుక్/ఖాతా, ఆధార్/DBT స్థితి.','అనుసంధానమైతే PM-KISAN నమోదు/స్థితి.','ప్రస్తుత రాష్ట్ర నిబంధనలు అనుమతించి కోరితే మాత్రమే కౌలు/భాగస్వామ్య సాగు ఆధారం.']},steps:{en:['Check the official Andhra Pradesh agriculture services.','Verify beneficiary records and current instalment notices with the local agriculture office.'],te:['ఆంధ్రప్రదేశ్ అధికారిక వ్యవసాయ సేవలను చూడండి.','స్థానిక వ్యవసాయ కార్యాలయంలో లబ్ధిదారుల రికార్డులు, ప్రస్తుత విడత నోటీసులను నిర్ధారించండి.']},officialUrl:'https://apagrisnet.gov.in/',category:'agriculture'},
{id:'ap-deepam-2',name:{en:'Deepam 2.0 LPG Support (Andhra Pradesh)',te:'దీపం 2.0 LPG సహాయం (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'Andhra Pradesh support initiative for eligible households receiving LPG cylinders. Confirm current beneficiary criteria, booking rules and benefit availability with official services.',te:'LPG సిలిండర్లు పొందే అర్హ కుటుంబాల కోసం ఆంధ్రప్రదేశ్ సహాయ కార్యక్రమం. ప్రస్తుత లబ్ధిదారుల ప్రమాణాలు, బుకింగ్ నియమాలు, ప్రయోజన అందుబాటును అధికారిక సేవలతో నిర్ధారించండి.'},eligibility:{en:['Deepam 2.0 benefit availability and eligibility are controlled by current Andhra Pradesh notifications and LPG beneficiary/connection records.','Eligibility may depend on an eligible household, a valid domestic LPG connection and current booking/subsidy conditions; not every cylinder or connection necessarily qualifies.','Connection-holder identity and household records may be matched against official databases; follow the current claim and booking process.','Confirm the current benefit count, booking window, payment/subsidy method and exclusions with the state or authorised LPG distributor.'],te:['దీపం 2.0 ప్రయోజన అందుబాటు, అర్హత ప్రస్తుత ఆంధ్రప్రదేశ్ ఉత్తర్వులు, LPG లబ్ధిదారు/కనెక్షన్ రికార్డులపై ఆధారపడి ఉంటాయి.','అర్హ కుటుంబం, చెల్లుబాటు అయ్యే దేశీయ LPG కనెక్షన్, ప్రస్తుత బుకింగ్/సబ్సిడీ షరతులు వర్తించవచ్చు; ప్రతి సిలిండర్/కనెక్షన్‌కు ప్రయోజనం హామీ కాదు.','కనెక్షన్ హోల్డర్ గుర్తింపు, కుటుంబ రికార్డులను అధికారిక డేటాబేస్‌తో సరిపోల్చవచ్చు; ప్రస్తుత క్లెయిమ్/బుకింగ్ విధానాన్ని అనుసరించండి.','ప్రయోజనాల సంఖ్య, బుకింగ్ గడువు, చెల్లింపు/సబ్సిడీ విధానం, మినహాయింపులను రాష్ట్రం లేదా అధీకృత LPG డిస్ట్రిబ్యూటర్‌తో నిర్ధారించండి.']},documents:{en:['Domestic LPG consumer number and active connection record.','Aadhaar and ration/family card details used for household verification as required.','Bank/DBT details if the benefit is transferred to an account.','LPG booking/cash memo or subsidy status if requested.','Confirm current rules with state and LPG distributor.'],te:['దేశీయ LPG వినియోగదారు నంబర్, క్రియాశీల కనెక్షన్ రికార్డు.','ప్రస్తుత ఉత్తర్వులు కోరే ఆధార్, రేషన్/కుటుంబ కార్డు వివరాలు.','బ్యాంకు/DBT వివరాలు, ప్రయోజనం ఖాతాకు బదిలీ అయితే.','అడిగితే LPG బుకింగ్/నగదు మెమో లేదా సబ్సిడీ స్థితి.','రాష్ట్రం, LPG డిస్ట్రిబ్యూటర్‌తో తాజా నియమాలను నిర్ధారించండి.']},steps:{en:['Check official state announcements and your LPG provider’s instructions.','Confirm eligibility, booking and claim status before relying on the benefit.'],te:['అధికారిక రాష్ట్ర ప్రకటనలు, LPG సేవాదారుడి సూచనలను చూడండి.','ప్రయోజనంపై ఆధారపడే ముందు అర్హత, బుకింగ్, క్లెయిమ్ స్థితిని నిర్ధారించండి.']},officialUrl:'https://apcfss.in/',category:'utilities'},
{id:'ap-stree-shakti',name:{en:'Stree Shakti Free Bus Travel (Andhra Pradesh)',te:'స్త్రీ శక్తి ఉచిత బస్సు ప్రయాణం (ఆంధ్రప్రదేశ్)'},scope:'state',states:['Andhra Pradesh'],summary:{en:'Andhra Pradesh public-transport benefit for eligible women and girls on designated state RTC services. Confirm eligible routes, passenger rules and launch/current operational details with APSRTC.',te:'ఎంచుకున్న రాష్ట్ర RTC సేవల్లో అర్హ మహిళలు, బాలికల కోసం ఆంధ్రప్రదేశ్ ప్రజా రవాణా ప్రయోజనం. అర్హ మార్గాలు, ప్రయాణికుల నియమాలు, ప్రస్తుత అమలు వివరాలను APSRTCతో నిర్ధారించండి.'},eligibility:{en:['APSRTC states free travel is for girls, women and transgender citizens domiciled in Andhra Pradesh, with valid ID proof. It applies to designated APSRTC services; check eligible bus types/routes and current operational conditions before travel.'],te:['అర్హత, మార్గాల కవరేజ్, ఆమోదించే గుర్తింపు ప్రస్తుత APSRTC, ప్రభుత్వ నిబంధనలకు లోబడి ఉంటాయి.']},documents:{en:['Valid Aadhaar or other ID accepted by current APSRTC rules.','Andhra Pradesh domicile/residence proof if requested for eligibility checks.','Routine travel may not need a separate application; eligible bus/route rules vary.','Check APSRTC\'s latest travel instructions.'],te:['ప్రస్తుత APSRTC నియమాలు అంగీకరించే ఆధార్ లేదా ఇతర చెల్లుబాటు ID.','అడిగితే ఆంధ్రప్రదేశ్ నివాస/స్థిర నివాస ఆధారం.','సాధారణ ప్రయాణానికి ప్రత్యేక దరఖాస్తు అవసరం లేకపోవచ్చు; బస్సు/మార్గ నియమాలు మారవచ్చు.','ప్రయాణానికి ముందు APSRTC తాజా సూచనలను చూడండి.']},steps:{en:['Review official Andhra Pradesh transport announcements.','Confirm eligible services and travel rules with APSRTC before travelling.'],te:['ఆంధ్రప్రదేశ్ అధికారిక రవాణా ప్రకటనలను చూడండి.','ప్రయాణానికి ముందు అర్హ సేవలు, నియమాలను APSRTCతో నిర్ధారించండి.']},officialUrl:'https://www.apsrtc.ap.gov.in/',category:'transport'}
];
export const schemes: Scheme[] = records.map(s=>({...s,verificationStatus:'needs-review',lastVerified:null}));
